23	
24	    /// Need a helper-struct to fight the lack of the function-template partial specialization.
25	    template <class T, bool is_const, bool is_ref = std::is_reference_v<T>>
26	    struct CastHelper;
27	
28	    template <class T>
29	    struct CastHelper<T, false, true>
30	    {
31	        auto & value(Base * ptr) { return typeid_cast<T>(*ptr); }
32	    };
33	
