38	    };
39	
40	    template <class T>
41	    struct CastHelper<T, false, false>
42	    {
43	        auto * value(Base * ptr) { return typeid_cast<T *>(ptr); }
44	    };
45	
46	    template <class T>
47	    struct CastHelper<T, true, false>
48	    {
49	        auto * value(const Base * ptr) { return typeid_cast<std::add_const_t<T> *>(ptr); }
50	    };
51	
52	public:
53	    template <class Derived>
54	    auto as() -> std::invoke_result_t<decltype(&CastHelper<Derived, false>::value), CastHelper<Derived, false>, Base *>
55	    {
56	        // TODO: if we do downcast to base type, then just return |this|.
57	        return CastHelper<Derived, false>().value(static_cast<Base *>(this));
58	    }
